const WithInitialFocus = () => {
    const [open, setOpen] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);

    const handleClose = () => setOpen(false);

    return (
        <div>
            <Button onClick={() => setOpen(true)}>Open modal</Button>
            <Modal
                size="medium"
                variant="default"
                open={open}
                onClose={handleClose}
                initialFocus={inputRef}>
                <Modal.Header>Modal with Initial Focus</Modal.Header>
                <Modal.Body>
                    <p>This modal demonstrates initial focus on the input field. When the
                                                modal opens, focus will be set to the input field instead of the
                                                default close button.</p>
                    <FormControl
                        ref={inputRef}
                        id="modal-fullname-input"
                        type="text"
                        placeholder="Your full name"
                        componentClass="input"
                        aria-label="Full name" />
                </Modal.Body>
                <Modal.Footer>
                    <Button block size="large" variant="primary">Submit</Button>
                    <Spacer size="xxs" />
                    <Button block size="large" onClick={handleClose}>Cancel</Button>
                </Modal.Footer>
            </Modal>
        </div>
    );
};

